package com.msarobotika.cyberdeck
import org.junit.Test
import org.junit.Assert.*
class PhoneReviewPolicyTest {
 private fun check(value:String="Activada",tone:PhoneTone=PhoneTone.INFO)=PhoneCheck("Depuración USB",value,"Observación de fixture, no lectura física",tone,"Seguridad")
 private fun item(c:PhoneCheck=check(),device:String="Owned fixture")=PhoneReviewPolicy.items(device,listOf(c)).single()
 @Test fun priorityUsesDeclaredToneWithoutInventingRiskScores(){val checks=PhoneTone.entries.mapIndexed{i,t->check(tone=t).copy(title="check$i")};assertEquals(listOf(PhoneTone.REVIEW,PhoneTone.UNKNOWN,PhoneTone.INFO,PhoneTone.OK),PhoneReviewPolicy.items("fixture",checks).map{it.check.tone})}
 @Test fun marksOnlyApplyToExactlyTheSameObservation(){val a=item();val record=PhoneReviewPolicy.update(emptyList(),a,true,"Revisado por el usuario").single();assertEquals(ReviewMark.CURRENT,PhoneReviewPolicy.status(item(),record));assertEquals(ReviewMark.STALE,PhoneReviewPolicy.status(item(check(value="Desactivada")),record));assertEquals(ReviewMark.STALE,PhoneReviewPolicy.status(item(check().copy(explanation="Contexto cambiado")),record));assertEquals(ReviewMark.STALE,PhoneReviewPolicy.status(item(check(tone=PhoneTone.REVIEW)),record))}
 @Test fun missingOrForeignRecordDoesNotBecomeCurrent(){val a=item();val record=PhoneReviewPolicy.update(emptyList(),item(device="another"),true,"").single();assertEquals(ReviewMark.PENDING,PhoneReviewPolicy.status(a,null));assertEquals(ReviewMark.PENDING,PhoneReviewPolicy.status(a,record))}
 @Test fun uncheckedNotesRemainPendingAndCanBeUpdated(){val a=item();val records=PhoneReviewPolicy.update(emptyList(),a,false,"Nota sin marcar");assertEquals(ReviewMark.PENDING,PhoneReviewPolicy.status(a,records.single()));val next=PhoneReviewPolicy.update(records,a,true,"Actualizada");assertEquals(1,next.size);assertEquals("Actualizada",next.single().note)}
 @Test fun codecPreservesUnicodeNotesAndManualFlags(){val records=PhoneReviewPolicy.update(emptyList(),item(),true,"Comprobación propia · 🔍");assertEquals(records,PhoneReviewCodec.decode(PhoneReviewCodec.encode(records)))}
 @Test fun invalidNotesDuplicatesAndFormatsAreRejected(){val a=item();assertTrue(runCatching{PhoneReviewPolicy.update(emptyList(),a,true,"x".repeat(601))}.isFailure);val r=PhoneReviewPolicy.update(emptyList(),a,true,"").single();assertTrue(runCatching{PhoneReviewCodec.encode(listOf(r,r))}.isFailure);assertTrue(runCatching{PhoneReviewCodec.decode("{\"format\":\"unknown\",\"records\":[]}")}.isFailure);assertTrue(runCatching{PhoneReviewCodec.encode(listOf(r.copy(key="../bad")))}.isFailure)}
 @Test fun ambiguousDuplicateObservationsAreRejected(){assertTrue(runCatching{PhoneReviewPolicy.items("fixture",listOf(check(),check()))}.isFailure)}
 @Test fun reportKeepsManualNotesSeparateFromObservedFacts(){val c=check();val i=item(c);val records=PhoneReviewPolicy.update(emptyList(),i,true,"Nota del usuario "+"😀".repeat(200));val snapshot=PhoneSnapshot("Owned fixture","2026-10-19T00:00:00Z",listOf(c),null,null,null,null,null,null,emptyList());val report=phoneReviewDiagnostic(snapshot,records);assertEquals("phone-review",diagnosticFromJson(report.toEvidenceJson()).kind);assertTrue(report.toEvidenceJson().toByteArray().size<=65536);assertTrue(report.details.any{it.second.contains("Nota del usuario") && it.second.contains(i.fingerprint)});assertTrue(report.summary.contains("manual"))}
}
